  class IntegrityEngine { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function generateManifest(string $targetDir, array $criticalFiles = []): array { if (empty($criticalFiles)) { $criticalFiles = [ 'composer.json', 'cli', 'bootstrap/app.php' ]; $appDir = $targetDir . '/app'; if (is_dir($appDir)) { $iterator = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($appDir)); foreach ($iterator as $file) { if ($file->isFile() && $file->getExtension() === 'php') { $criticalFiles[] = str_replace($targetDir . '/', '', $file->getPathname()); } } } } $filesManifest = []; foreach ($criticalFiles as $f) { $fullPath = $targetDir . '/' . $f; if (file_exists($fullPath)) { $filesManifest[$f] = [ 'hash' => hash_file('sha256', $fullPath), 'size' => filesize($fullPath), 'mtime' => filemtime($fullPath) ]; } } $integrityData = [ 'product' => 'Veltrion Framework Commercial Build', 'timestamp' => date('Y-m-d H:i:s'), 'algorithm' => 'SHA-256', 'files_count' => count($filesManifest), 'files' => $filesManifest ]; $manifestPath = $targetDir . '/integrity-manifest.json'; file_put_contents($manifestPath, json_encode($integrityData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); return [ 'manifest_path' => $manifestPath, 'files_hashed' => count($filesManifest) ]; } public function verifyIntegrity(string $targetDir): array { $manifestPath = $targetDir . '/integrity-manifest.json'; if (!file_exists($manifestPath)) { return [ 'status' => 'NO_MANIFEST', 'valid' => true, 'message' => 'Integrity manifest not present. Skipping strict integrity check.' ]; } $manifest = json_decode(file_get_contents($manifestPath), true); if (!isset($manifest['files'])) { return [ 'status' => 'TAMPER_DETECTED', 'valid' => false, 'message' => 'Integrity manifest corrupted or invalid format.' ]; } $modifiedFiles = []; $missingFiles = []; foreach ($manifest['files'] as $relPath => $meta) { $fullPath = $targetDir . '/' . $relPath; if (!file_exists($fullPath)) { $missingFiles[] = $relPath; continue; } $currentHash = hash_file('sha256', $fullPath); if ($currentHash !== $meta['hash']) { $modifiedFiles[] = $relPath; } } $isValid = empty($modifiedFiles) && empty($missingFiles); return [ 'status' => $isValid ? 'INTEGRITY_OK' : 'TAMPER_DETECTED', 'valid' => $isValid, 'modified_files' => $modifiedFiles, 'missing_files' => $missingFiles, 'checked_files_count' => count($manifest['files']) ]; } } 